    정인: { 희:['재','식상'], 기:[],
      원문:'正官佩印，運喜財鄉，傷食反吉。',
      조건: c => !c.신강 && c.sery.관살 >= 2.0
        ? { 희:['비겁','인'], 기:['재'], 비고:'官重身輕이면 身旺이 우선이고 財運은 필요치 않다' } : null },
    _기본: { 희:['재','인'], 기:['상관','편관'],
      원문:'正官而用財印，身稍輕則取助身，官稍輕則助官。' },
